import { ZIG_VERSION } from './config.mjs';
import { TB_VERSION } from './config.mjs';
import { tigerbeetleChapters } from './tigerbeetle-course.mjs';
import { zigTigerStyleChapters } from './zig-tigerstyle-course.mjs';

const code = (id, title, minutes, description, body, task, starter, solution, tests, hints, reference) => ({
  id, title, kind: 'exercise', minutes, description, body, task, starter, solution, tests, hints, reference,
});
const quiz = (id, title, questions) => ({ id, title, kind: 'quiz', minutes: 5, description: 'Check your understanding. Every answer comes with an explanation.', questions });
const q = (prompt, options, answer, explanation) => ({ prompt, options, answer, explanation });
const test = (name, body) => `test "${name}" {\n${body}\n}\n`;
const chapter = (id, title, description, icon, lessons) => ({ id, title, description, icon, lessons });

const zigChapters = [
  chapter('first-sparks', 'First sparks', 'Meet the compiler. Give your ideas a type.', '01', [
    {
      id: 'welcome', title: 'Your local workshop', kind: 'reading', minutes: 4,
      description: 'A small language. A lot of possibilities.',
      body: `Zig is a systems programming language built around explicit control. You choose when memory is allocated, how errors are handled, and which work happens at compile time. This course starts with small programs and ends with a tested ledger parser.\n\n## How this workshop works\nRead a short explanation, change the code, and select **Check solution**. The app invokes a real Zig compiler on your own computer. Compiler errors and test results appear in the terminal. You can inspect the tests, reveal progressive hints, or study a solution when you get stuck.\n\nEvery chapter ends with a quiz. Correct answers earn XP once; retries cost nothing. Your code, quiz attempts, and progress are saved on this machine. You can revisit any lesson in any order.\n\n## Three commands to know\n\`\`\`sh\nzig run main.zig\nzig test main.zig\nzig build-exe main.zig\n\`\`\`\n**run** compiles and executes a program. **test** compiles and executes its test blocks. **build-exe** produces a native executable. In the playground, you can use all three. In exercises, the app supplies a separate test file so your changes are checked against examples and edge cases.\n\n## Read the compiler\nA compiler message includes a file, line, column, and explanation. Start with the first error: later messages often follow from it. Zig treats unused local variables and variables declared with var but never mutated as errors. That feedback helps you express your intent.\n\n## Your environment\nThis course targets **Zig ${ZIG_VERSION}**. Once the compiler is installed, the app and lessons work without an internet connection. The Environment panel shows the compiler version and execution mode. The official language reference is linked from each lesson and bundled locally during setup.`,
      reference: 'Introduction',
    },
    code('hello-zig', 'Hello, Zig', 5, 'Make your first native program say hello.',
      'A Zig program starts in a public main function. Import the standard library with @import("std"). std.debug.print takes a format string and a tuple of arguments; .{} is an empty tuple. It writes to stderr, which this app displays alongside stdout.\n\n```zig\nconst std = @import("std");\npub fn main() void {\n    std.debug.print("Found {d} sparks\\n", .{3});\n}\n```\nA semicolon ends a statement. The return type void means that main returns no value.',
      'Change the greeting so the program prints exactly `Hello, Zig!` followed by a newline.',
      'const std = @import("std");\n\npub fn main() void {\n    std.debug.print("Hello, world!\\n", .{});\n}\n',
      'const std = @import("std");\n\npub fn main() void {\n    std.debug.print("Hello, Zig!\\n", .{});\n}\n',
      null, ['Keep main public so the executable can find its entry point.', 'Change world to Zig inside the string. Keep the \\n escape.'], 'Hello-World'),
    code('values', 'Values with intention', 7, 'Use const, var, and explicit integer types.',
      'Use const for a binding you will not reassign and var when a value changes. An integer type starts with u (unsigned) or i (signed), followed by its bit width: u8 can represent 0 through 255. Zig infers a type when enough context is available.\n\n```zig\nconst max_health: u16 = 100;\nvar health: u16 = 80;\nhealth += 5;\n```\nThe pub keyword makes a declaration visible to other files. Our test harness imports your file, so the declarations requested below must be public.',
      'Set the public constant `starting_health` to 100 (u16). Implement `heal` so it returns health + amount, capped at starting_health. Inputs may be any u16 values, so add in u32 before capping.',
      'pub const starting_health: u16 = 0;\n\npub fn heal(health: u16, amount: u16) u16 {\n    return health -| amount;\n}\n',
      'pub const starting_health: u16 = 100;\n\npub fn heal(health: u16, amount: u16) u16 {\n    const total: u32 = @as(u32, health) + amount;\n    return @intCast(@min(total, starting_health));\n}\n',
      test('health cap', '    try std.testing.expectEqual(@as(u16, 100), learner.starting_health);\n    try std.testing.expectEqual(@as(u16, 85), learner.heal(80, 5));\n    try std.testing.expectEqual(@as(u16, 100), learner.heal(90, 40));') + test('zero and large inputs', '    try std.testing.expectEqual(@as(u16, 0), learner.heal(0, 0));\n    try std.testing.expectEqual(@as(u16, 100), learner.heal(65535, 65535));'),
      ['Use @as(u32, health) to widen before addition. An addition in u16 could overflow.', '@min(total, starting_health) caps the result. @intCast converts it back to the inferred u16 return type.'], 'Variables'),
    code('functions', 'Functions that do one thing', 7, 'Give inputs and outputs a clear contract.',
      'Functions declare parameter types and a return type. Parameters are immutable; use local var declarations if you need changing state. Return a value with return.\n\n```zig\npub fn double(value: i32) i32 {\n    return value * 2;\n}\n```\nZig checks both the types and the visibility of your function. Tests call a function with several inputs to check its behavior.',
      'Implement `energyCost(steps, cost_per_step)` to multiply the two u16 inputs and return a u32. Widen before multiplying so large inputs work.',
      'pub fn energyCost(steps: u16, cost_per_step: u16) u32 {\n    return @as(u32, steps) + cost_per_step;\n}\n',
      'pub fn energyCost(steps: u16, cost_per_step: u16) u32 {\n    return @as(u32, steps) * cost_per_step;\n}\n',
      test('energy usage', '    try std.testing.expectEqual(@as(u32, 30), learner.energyCost(10, 3));\n    try std.testing.expectEqual(@as(u32, 0), learner.energyCost(0, 99));\n    try std.testing.expectEqual(@as(u32, 4294836225), learner.energyCost(65535, 65535));'),
      ['The result of an arithmetic expression depends on its operand types.', 'Widen steps with @as(u32, steps), then multiply by cost_per_step.'], 'Functions'),
    quiz('quiz-foundations', 'Checkpoint: foundations', [
      q('Which declaration communicates that a binding will never be reassigned?', ['const speed: u8 = 12;', 'var speed: u8 = 12;', 'pub fn speed() void {}'], 0, 'const prevents reassignment of the binding. Use var only when a value will change.'),
      q('Why is main declared pub?', ['It enables dynamic memory.', 'It makes the program entry point visible.', 'It turns off runtime checks.'], 1, 'The executable startup code must be able to access main.'),
      q('What is the largest value that fits in a u8?', ['127', '256', '255'], 2, 'An unsigned 8-bit integer has 256 possible values, from 0 through 255.'),
    ]),
  ]),
  chapter('data-shapes', 'Give data a shape', 'Numbers, arrays, strings, and slices.', '02', [
    code('casting', 'Make the conversion explicit', 7, 'Turn small integers into safe calculations.',
      'Zig permits safe widening, such as u8 to u32. Narrowing requires @intCast, which uses its surrounding type as the destination and checks range in safe modes. @as gives an expression an explicit type.\n\n```zig\nconst small: u8 = 200;\nconst wide = @as(u32, small) * 2;\n```\nCasting the result after an overflowing operation is too late. Widen an operand first.',
      'Implement `square(value: u8) u32`. It must work for all u8 values, including 255.',
      'pub fn square(value: u8) u32 {\n    return value;\n}\n',
      'pub fn square(value: u8) u32 {\n    return @as(u32, value) * value;\n}\n',
      test('square without overflow', '    try std.testing.expectEqual(@as(u32, 0), learner.square(0));\n    try std.testing.expectEqual(@as(u32, 49), learner.square(7));\n    try std.testing.expectEqual(@as(u32, 65025), learner.square(255));'),
      ['A u8 multiplication cannot represent 255 * 255.', 'Return @as(u32, value) * value.'], 'Casting'),
    code('arrays', 'A fixed-size inventory', 8, 'Work with arrays whose length is part of their type.',
      'An array type includes a length: [3]u16 contains exactly three u16 values. The literal [_]u16{ 4, 5, 6 } asks the compiler to infer the length. Indexing starts at zero. The .len field gives the number of elements.\n\n```zig\nconst slots = [_]u16{ 4, 5, 6 };\nconst first = slots[0];\n```\nA for loop visits elements without manual indexing. Use a wider accumulator when a sum could exceed an element’s range.',
      'Implement `inventoryTotal(items: [4]u16) u32` to sum all four item counts.',
      'pub fn inventoryTotal(items: [4]u16) u32 {\n    return items[0];\n}\n',
      'pub fn inventoryTotal(items: [4]u16) u32 {\n    var total: u32 = 0;\n    for (items) |item| total += item;\n    return total;\n}\n',
      test('sum all inventory slots', '    try std.testing.expectEqual(@as(u32, 20), learner.inventoryTotal(.{ 2, 4, 6, 8 }));\n    try std.testing.expectEqual(@as(u32, 0), learner.inventoryTotal(.{ 0, 0, 0, 0 }));\n    try std.testing.expectEqual(@as(u32, 262140), learner.inventoryTotal(.{ 65535, 65535, 65535, 65535 }));'),
      ['Start with var total: u32 = 0.', 'for (items) |item| total += item; visits all four slots.'], 'Arrays'),
    code('slices', 'A view into memory', 8, 'Read strings and buffers without copying them.',
      'A slice is a pointer and a length. []const u8 is a read-only slice of bytes, commonly used for strings. Unlike an array, a slice’s length can vary at runtime. A slice borrows existing memory; it does not allocate or copy that memory.\n\n```zig\nconst word: []const u8 = "forge";\nconst middle = word[1..4]; // "org"\n```\nString length counts bytes, which may differ from the number of Unicode characters. A byte literal uses single quotes, such as \'a\'.',
      'Implement `countByte(text, needle)` to count occurrences of a byte. Empty slices must return zero.',
      'pub fn countByte(text: []const u8, needle: u8) usize {\n    _ = needle;\n    return text.len;\n}\n',
      'pub fn countByte(text: []const u8, needle: u8) usize {\n    var count: usize = 0;\n    for (text) |byte| {\n        if (byte == needle) count += 1;\n    }\n    return count;\n}\n',
      test('count bytes', '    try std.testing.expectEqual(@as(usize, 3), learner.countByte("banana", \'a\'));\n    try std.testing.expectEqual(@as(usize, 0), learner.countByte("", \'a\'));\n    try std.testing.expectEqual(@as(usize, 0), learner.countByte("zig", \'x\'));\n    try std.testing.expectEqual(@as(usize, 4), learner.countByte("zzzz", \'z\'));'),
      ['Use a usize counter, the natural type for lengths and indexes.', 'Remove _ = needle when you use needle in an equality comparison.'], 'Slices'),
    quiz('quiz-data', 'Checkpoint: data', [
      q('What does []const u8 describe?', ['An array of exactly 8 bytes', 'A read-only slice of bytes', 'A pointer that owns its memory'], 1, 'A slice carries a pointer and length. const prevents mutation through this view; ownership is a separate concern.'),
      q('What is the type of [_]u8{ 1, 2, 3 }?', ['[3]u8', '[]u8', 'u24'], 0, 'The underscore asks Zig to infer the array length from its three elements.'),
      q('When should you widen an operand to prevent overflow?', ['After multiplication', 'Only when printing', 'Before multiplication'], 2, 'The arithmetic must take place in the wider type. Casting after overflow cannot repair the lost information.'),
    ]),
  ]),
  chapter('control-flow', 'Choose your path', 'Branch, iterate, and handle every case.', '03', [
    code('conditions', 'Decisions are expressions', 7, 'Use if to choose a return value.',
      'An if expression can produce a value. Its condition must be bool; Zig does not treat nonzero integers as true.\n\n```zig\nconst label = if (temperature > 30) "hot" else "cool";\n```\nUse else if for multiple ranges. Watch boundaries: testing exactly at a threshold catches common mistakes.',
      'Implement `rank(xp)` returning a byte slice: "novice" below 100, "apprentice" from 100 through 499, and "builder" at 500 or higher.',
      'pub fn rank(xp: u32) []const u8 {\n    return if (xp > 0) "builder" else "novice";\n}\n',
      'pub fn rank(xp: u32) []const u8 {\n    return if (xp < 100) "novice" else if (xp < 500) "apprentice" else "builder";\n}\n',
      test('rank boundaries', '    try std.testing.expectEqualStrings("novice", learner.rank(0));\n    try std.testing.expectEqualStrings("novice", learner.rank(99));\n    try std.testing.expectEqualStrings("apprentice", learner.rank(100));\n    try std.testing.expectEqualStrings("apprentice", learner.rank(499));\n    try std.testing.expectEqualStrings("builder", learner.rank(500));'),
      ['Check the lowest threshold first, then the next.', 'Use xp < 100, then xp < 500. Everything else is builder.'], 'if'),
    code('loops', 'Let the loop do the work', 9, 'Accumulate a result and skip unwanted items.',
      'A for loop captures each element between vertical bars. A while loop repeats while its condition is true and can include a continuation expression: while (i < 10) : (i += 1). continue skips the current iteration; break exits.\n\n```zig\nvar total: u64 = 0;\nfor (values) |value| {\n    if (value == 0) continue;\n    total += value;\n}\n```\nThe modulo operator % gives the remainder for unsigned integers. Even integers have remainder zero when divided by two.',
      'Implement `sumEven(values: []const u16) u64` to sum only even values. The slice can be empty.',
      'pub fn sumEven(values: []const u16) u64 {\n    var total: u64 = 0;\n    for (values) |value| total += value;\n    return total;\n}\n',
      'pub fn sumEven(values: []const u16) u64 {\n    var total: u64 = 0;\n    for (values) |value| {\n        if (value % 2 == 0) total += value;\n    }\n    return total;\n}\n',
      test('sum even values only', '    try std.testing.expectEqual(@as(u64, 12), learner.sumEven(&.{ 1, 2, 3, 4, 6 }));\n    try std.testing.expectEqual(@as(u64, 0), learner.sumEven(&.{}));\n    try std.testing.expectEqual(@as(u64, 0), learner.sumEven(&.{ 1, 3, 5 }));\n    try std.testing.expectEqual(@as(u64, 65534), learner.sumEven(&.{ 65534, 65535 }));'),
      ['Filter with value % 2 == 0.', 'Keep the accumulator outside the loop and return it after the loop.'], 'for'),
    code('switch', 'Every direction covered', 8, 'Use an exhaustive switch over an enum.',
      'An enum names a set of distinct values. A switch over an enum must cover every case unless it has an else branch. That lets the compiler help when you add a new value later.\n\n```zig\nconst Mode = enum { quiet, loud };\nconst volume: u8 = switch (mode) {\n    .quiet => 10,\n    .loud => 90,\n};\n```\nMultiple cases can share a branch: .north, .south => 2.',
      'Implement `travelCost(direction)`: north and south cost 2, east costs 3, west costs 5. Use the provided Direction enum.',
      'pub const Direction = enum { north, south, east, west };\n\npub fn travelCost(direction: Direction) u8 {\n    return switch (direction) {\n        .north, .south, .east, .west => 0,\n    };\n}\n',
      'pub const Direction = enum { north, south, east, west };\n\npub fn travelCost(direction: Direction) u8 {\n    return switch (direction) {\n        .north, .south => 2,\n        .east => 3,\n        .west => 5,\n    };\n}\n',
      test('all directions', '    try std.testing.expectEqual(@as(u8, 2), learner.travelCost(.north));\n    try std.testing.expectEqual(@as(u8, 2), learner.travelCost(.south));\n    try std.testing.expectEqual(@as(u8, 3), learner.travelCost(.east));\n    try std.testing.expectEqual(@as(u8, 5), learner.travelCost(.west));'),
      ['Keep north and south in a shared branch.', 'Each branch ends with a comma; the switch expression ends with a semicolon.'], 'switch'),
    quiz('quiz-control', 'Checkpoint: control flow', [
      q('What does continue do in a loop?', ['Exits the whole function', 'Starts the next iteration', 'Ends the loop permanently'], 1, 'continue skips the remaining body and proceeds to the next iteration; a while continuation expression still executes.'),
      q('What happens if an enum switch misses a case and has no else?', ['The missing case returns zero', 'It silently skips the branch', 'Compilation fails'], 2, 'Zig enforces exhaustive switching, catching missing cases before execution.'),
      q('Which condition checks whether an unsigned integer n is even?', ['n % 2 == 0', 'n / 2 == 0', 'n == true'], 0, 'Even numbers have a remainder of zero after division by two.'),
    ]),
  ]),
  chapter('model-world', 'Model a small world', 'Structs, methods, and tagged unions.', '04', [
    code('structs', 'Data that belongs together', 9, 'Put a rectangle and its behavior in one place.',
      'A struct groups named fields. Methods are functions declared inside a struct; a first parameter named self is conventional, not magical. Calling rect.area() passes rect as self.\n\n```zig\nconst Point = struct {\n    x: i32,\n    y: i32,\n    pub fn sum(self: Point) i32 {\n        return self.x + self.y;\n    }\n};\n```\nDeclare a method pub when another file needs to call it.',
      'Implement Rectangle.area() and Rectangle.perimeter(). Width and height are u16; both results are u32. Zero dimensions are valid.',
      'pub const Rectangle = struct {\n    width: u16,\n    height: u16,\n\n    pub fn area(self: Rectangle) u32 {\n        return self.width;\n    }\n\n    pub fn perimeter(self: Rectangle) u32 {\n        return self.height;\n    }\n};\n',
      'pub const Rectangle = struct {\n    width: u16,\n    height: u16,\n\n    pub fn area(self: Rectangle) u32 {\n        return @as(u32, self.width) * self.height;\n    }\n\n    pub fn perimeter(self: Rectangle) u32 {\n        return 2 * (@as(u32, self.width) + self.height);\n    }\n};\n',
      test('rectangle methods', '    const rect = learner.Rectangle{ .width = 4, .height = 7 };\n    try std.testing.expectEqual(@as(u32, 28), rect.area());\n    try std.testing.expectEqual(@as(u32, 22), rect.perimeter());\n    const big = learner.Rectangle{ .width = 65535, .height = 65535 };\n    try std.testing.expectEqual(@as(u32, 4294836225), big.area());\n    try std.testing.expectEqual(@as(u32, 262140), big.perimeter());\n    const zero = learner.Rectangle{ .width = 0, .height = 0 };\n    try std.testing.expectEqual(@as(u32, 0), zero.area());'),
      ['Area is width * height. Perimeter is 2 * (width + height).', 'Widen width to u32 before addition or multiplication.'], 'struct'),
    code('enum-methods', 'Names instead of magic numbers', 8, 'Attach behavior to a small set of states.',
      'Enums make invalid states harder to express. A Status parameter can only take a declared status. Enums can also have methods. @tagName(value) returns the name of an enum tag as text.\n\n```zig\nconst State = enum {\n    idle,\n    active,\n    pub fn isActive(self: State) bool {\n        return self == .active;\n    }\n};\n```\nA switch expression is useful when each tag maps to a different value.',
      'Implement `Status.label()` to return "Queued", "Running", or "Done" for queued, running, or done. Implement `isFinished()` so only done returns true.',
      'pub const Status = enum {\n    queued, running, done,\n\n    pub fn label(self: Status) []const u8 {\n        return @tagName(self);\n    }\n\n    pub fn isFinished(self: Status) bool {\n        return self == .running;\n    }\n};\n',
      'pub const Status = enum {\n    queued, running, done,\n\n    pub fn label(self: Status) []const u8 {\n        return switch (self) {\n            .queued => "Queued",\n            .running => "Running",\n            .done => "Done",\n        };\n    }\n\n    pub fn isFinished(self: Status) bool {\n        return self == .done;\n    }\n};\n',
      test('status labels and completion', '    try std.testing.expectEqualStrings("Queued", learner.Status.queued.label());\n    try std.testing.expectEqualStrings("Running", learner.Status.running.label());\n    try std.testing.expectEqualStrings("Done", learner.Status.done.label());\n    try std.testing.expect(!learner.Status.queued.isFinished());\n    try std.testing.expect(!learner.Status.running.isFinished());\n    try std.testing.expect(learner.Status.done.isFinished());'),
      ['@tagName returns the original lowercase spelling, but the task needs capitalized labels.', 'Use a switch for labels and self == .done for completion.'], 'enum'),
    code('tagged-unions', 'One event, several shapes', 10, 'Capture the payload of a tagged union.',
      'A tagged union stores one of several payload types plus a tag recording which one is active. union(enum) creates that tag automatically. A switch safely captures the active payload.\n\n```zig\nconst Message = union(enum) {\n    count: u32,\n    quit: void,\n};\nconst n = switch (message) {\n    .count => |value| value,\n    .quit => 0,\n};\n```\nReading an inactive field directly is invalid. Switch on the union to let Zig check your access.',
      'Implement `delta(event) i64`: a deposit adds its u32 amount, a withdrawal subtracts it, and a heartbeat changes nothing.',
      'pub const Event = union(enum) {\n    deposit: u32,\n    withdrawal: u32,\n    heartbeat: void,\n};\n\npub fn delta(event: Event) i64 {\n    return switch (event) {\n        .deposit => |amount| amount,\n        .withdrawal => |amount| amount,\n        .heartbeat => 1,\n    };\n}\n',
      'pub const Event = union(enum) {\n    deposit: u32,\n    withdrawal: u32,\n    heartbeat: void,\n};\n\npub fn delta(event: Event) i64 {\n    return switch (event) {\n        .deposit => |amount| amount,\n        .withdrawal => |amount| -@as(i64, amount),\n        .heartbeat => 0,\n    };\n}\n',
      test('event payloads', '    try std.testing.expectEqual(@as(i64, 75), learner.delta(.{ .deposit = 75 }));\n    try std.testing.expectEqual(@as(i64, -20), learner.delta(.{ .withdrawal = 20 }));\n    try std.testing.expectEqual(@as(i64, 0), learner.delta(.heartbeat));\n    try std.testing.expectEqual(@as(i64, -4294967295), learner.delta(.{ .withdrawal = 4294967295 }));'),
      ['Capture each amount with |amount| in its switch branch.', 'Convert an unsigned withdrawal to i64 before negating it.'], 'Tagged-union'),
    quiz('quiz-models', 'Checkpoint: modeling', [
      q('What makes a tagged union safe to switch over?', ['All payloads are always initialized', 'The tag records which payload is active', 'Every payload has the same size'], 1, 'The tag identifies the active variant, so each switch branch can access the correct payload type.'),
      q('What does rect.area() do when area has a self parameter?', ['Copies the whole application', 'Allocates a new Rectangle', 'Passes rect as the first argument'], 2, 'Method call syntax supplies the value before the dot as the first parameter.'),
      q('Why use an enum for a task status?', ['It restricts values to declared states', 'It makes every operation faster', 'It gives every state a text buffer'], 0, 'Enums model a closed set of named choices and support exhaustive compiler checks.'),
    ]),
  ]),
  chapter('honest-contracts', 'Write honest contracts', 'Pointers, missing values, and errors.', '05', [
    code('pointers', 'Change the original', 9, 'Use a pointer to mutate a caller’s value.',
      'A *T pointer refers to one value of type T. Take an address with &value and dereference a pointer with pointer.*. A *const T cannot be used to change the value it points to.\n\n```zig\nfn reset(value: *u32) void {\n    value.* = 0;\n}\n```\nPointers do not automatically own or extend the lifetime of the memory they reference. Never return a pointer to a local variable that goes out of scope.',
      'Implement `swap(a: *i32, b: *i32)` to exchange the pointed-to values. It must also work when both pointers refer to the same value.',
      'pub fn swap(a: *i32, b: *i32) void {\n    a.* = b.*;\n}\n',
      'pub fn swap(a: *i32, b: *i32) void {\n    const original = a.*;\n    a.* = b.*;\n    b.* = original;\n}\n',
      test('swap pointed-to values', '    var a: i32 = -7;\n    var b: i32 = 42;\n    learner.swap(&a, &b);\n    try std.testing.expectEqual(@as(i32, 42), a);\n    try std.testing.expectEqual(@as(i32, -7), b);\n    learner.swap(&a, &a);\n    try std.testing.expectEqual(@as(i32, 42), a);'),
      ['Save a.* in a const before overwriting it.', 'Assign a.* = b.*, then assign the saved original to b.*.'], 'Pointers'),
    code('optionals', 'Missing is a valid answer', 9, 'Return either an index or null.',
      'An optional ?T contains a T or null. This expresses absence without a special sentinel such as -1. Unwrap safely with if or provide a fallback with orelse.\n\n```zig\nconst index: ?usize = null;\nconst fallback = index orelse 0;\nif (index) |found| {\n    // found is a usize here\n}\n```\nUse for (items, 0..) |item, index| when you need both values and indexes.',
      'Implement `findIndex(values, needle) ?usize`. Return the index of the first match, or null if no match exists.',
      'pub fn findIndex(values: []const u8, needle: u8) ?usize {\n    for (values, 0..) |value, index| {\n        if (value == needle) return index;\n    }\n    return 0;\n}\n',
      'pub fn findIndex(values: []const u8, needle: u8) ?usize {\n    for (values, 0..) |value, index| {\n        if (value == needle) return index;\n    }\n    return null;\n}\n',
      test('first match or absence', '    try std.testing.expectEqual(@as(?usize, 1), learner.findIndex("banana", \'a\'));\n    try std.testing.expectEqual(@as(?usize, 0), learner.findIndex("zig", \'z\'));\n    try std.testing.expectEqual(@as(?usize, null), learner.findIndex("zig", \'x\'));\n    try std.testing.expectEqual(@as(?usize, null), learner.findIndex("", \'x\'));'),
      ['Zero is a valid index, so it cannot stand for not found.', 'Return null after the loop if no iteration returned an index.'], 'Optionals'),
    code('errors', 'Failure belongs in the type', 10, 'Return an error union and preserve its meaning.',
      'An error union E!T contains a value of type T or an error from set E. !T infers the error set. try returns an error to the caller, while catch handles it locally.\n\n```zig\nfn requirePositive(n: i32) !i32 {\n    if (n <= 0) return error.NotPositive;\n    return n;\n}\n```\nUse @divTrunc for signed division with truncation toward zero. Division by zero must be rejected before you divide.',
      'Implement `divide(a: i32, b: i32) !i32`. Return error.DivisionByZero when b is zero and error.Overflow for the minimum i32 divided by -1. Otherwise return the quotient truncated toward zero.',
      'pub fn divide(a: i32, b: i32) !i32 {\n    if (b == 0) return 0;\n    return @divTrunc(a, b);\n}\n',
      'pub fn divide(a: i32, b: i32) !i32 {\n    if (b == 0) return error.DivisionByZero;\n    if (a == -2147483648 and b == -1) return error.Overflow;\n    return @divTrunc(a, b);\n}\n',
      test('valid quotients', '    try std.testing.expectEqual(@as(i32, 3), try learner.divide(10, 3));\n    try std.testing.expectEqual(@as(i32, -3), try learner.divide(-10, 3));\n    try std.testing.expectEqual(@as(i32, 0), try learner.divide(0, 4));') + test('division failures', '    try std.testing.expectError(error.DivisionByZero, learner.divide(7, 0));\n    try std.testing.expectError(error.Overflow, learner.divide(-2147483648, -1));'),
      ['Guard both invalid cases before @divTrunc.', 'The minimum signed i32 is -2147483648. Its positive counterpart does not fit in i32.'], 'Errors'),
    quiz('quiz-contracts', 'Checkpoint: contracts', [
      q('What does ?usize represent?', ['An index that can be negative', 'Either a usize value or null', 'A pointer to an index'], 1, 'Optional types explicitly represent a value or its absence.'),
      q('What does try do when an expression returns an error?', ['Retries the expression', 'Converts the error to zero', 'Returns that error from the current function'], 2, 'try unwraps success and propagates failure. The caller’s return type must permit the error.'),
      q('Which expression changes the value addressed by a *i32 pointer named p?', ['p.* = 10;', 'p = 10;', '&p = 10;'], 0, 'p.* dereferences the pointer; assigning it updates the pointed-to value.'),
    ]),
  ]),
  chapter('memory', 'Own your memory', 'Clean up deliberately. Make allocation visible.', '06', [
    code('defer', 'Leave a clean workspace', 9, 'Run cleanup at scope exit, including errors.',
      'defer schedules a statement for the end of its current scope. Deferred statements run in reverse order of registration, whether you return a value or an error. errdefer runs only when that scope exits with an error.\n\n```zig\nconst bytes = try allocator.alloc(u8, 10);\ndefer allocator.free(bytes);\n```\nRegister cleanup immediately after acquiring a resource. You can then focus on the useful work.',
      'Fix `visit(active, should_fail)`: increment active on entry, always decrement it when the function exits, return error.Cancelled when should_fail is true, otherwise return 42. Both paths must leave active unchanged overall.',
      'pub fn visit(active: *u32, should_fail: bool) !u32 {\n    active.* += 1;\n    if (should_fail) return error.Cancelled;\n    active.* -= 1;\n    return 42;\n}\n',
      'pub fn visit(active: *u32, should_fail: bool) !u32 {\n    active.* += 1;\n    defer active.* -= 1;\n    if (should_fail) return error.Cancelled;\n    return 42;\n}\n',
      test('cleanup on success and failure', '    var active: u32 = 3;\n    try std.testing.expectEqual(@as(u32, 42), try learner.visit(&active, false));\n    try std.testing.expectEqual(@as(u32, 3), active);\n    try std.testing.expectError(error.Cancelled, learner.visit(&active, true));\n    try std.testing.expectEqual(@as(u32, 3), active);'),
      ['The error path returns before the current decrement.', 'Move the decrement into defer immediately after the increment.'], 'defer'),
    code('allocation', 'Ask for memory explicitly', 12, 'Allocate an owned copy and let the caller free it.',
      'Zig has no hidden default allocator. A function that allocates usually accepts std.mem.Allocator. allocator.alloc(T, count) returns ![]T and the caller must eventually free that slice.\n\n```zig\nconst buffer = try allocator.alloc(u8, input.len);\n@memcpy(buffer, input);\nreturn buffer;\n```\nDo not defer freeing a buffer you return: ownership transfers to the caller. Tests use std.testing.allocator to detect leaks.',
      'Implement `duplicate(allocator, input) ![]u8` to allocate and return an independent copy of input. The caller owns and frees the result. Empty input is valid.',
      'const std = @import("std");\n\npub fn duplicate(allocator: std.mem.Allocator, input: []const u8) ![]u8 {\n    return try allocator.alloc(u8, input.len);\n}\n',
      'const std = @import("std");\n\npub fn duplicate(allocator: std.mem.Allocator, input: []const u8) ![]u8 {\n    const result = try allocator.alloc(u8, input.len);\n    @memcpy(result, input);\n    return result;\n}\n',
      test('independent owned copy', '    var source = [_]u8{ \'z\', \'i\', \'g\' };\n    const result = try learner.duplicate(std.testing.allocator, &source);\n    defer std.testing.allocator.free(result);\n    try std.testing.expectEqualStrings("zig", result);\n    source[0] = \'b\';\n    try std.testing.expectEqualStrings("zig", result);') + test('empty and allocation failure', '    const result = try learner.duplicate(std.testing.allocator, "");\n    defer std.testing.allocator.free(result);\n    try std.testing.expectEqual(@as(usize, 0), result.len);\n    try std.testing.expectError(error.OutOfMemory, learner.duplicate(std.testing.failing_allocator, "zig"));'),
      ['An allocated buffer starts uninitialized. Fill it before returning.', '@memcpy(result, input) copies the bytes. try propagates OutOfMemory.'], 'Memory'),
    code('errdefer', 'Clean up partial success', 13, 'Keep ownership correct when a later allocation fails.',
      'If one allocation succeeds and a second fails, the first still needs cleanup. errdefer releases it only on an error, preserving ownership on success.\n\n```zig\nconst first = try allocator.dupe(u8, a);\nerrdefer allocator.free(first);\nconst second = try allocator.dupe(u8, b);\nreturn .{ .first = first, .second = second };\n```\nA plain defer would also free first on success, leaving the returned slice dangling. Resource ownership is a contract between caller and callee.',
      'Implement `copyPair`: return independently owned copies of a and b in Pair. Free any earlier allocation if a later allocation fails. The caller frees both fields on success. The tests exercise every allocation failure point.',
      'const std = @import("std");\npub const Pair = struct { first: []u8, second: []u8 };\n\npub fn copyPair(allocator: std.mem.Allocator, a: []const u8, b: []const u8) !Pair {\n    const first = try allocator.dupe(u8, a);\n    const second = try allocator.dupe(u8, b);\n    return .{ .first = first, .second = second };\n}\n',
      'const std = @import("std");\npub const Pair = struct { first: []u8, second: []u8 };\n\npub fn copyPair(allocator: std.mem.Allocator, a: []const u8, b: []const u8) !Pair {\n    const first = try allocator.dupe(u8, a);\n    errdefer allocator.free(first);\n    const second = try allocator.dupe(u8, b);\n    return .{ .first = first, .second = second };\n}\n',
      'fn checkPair(allocator: std.mem.Allocator) !void {\n    const pair = try learner.copyPair(allocator, "hello", "zig");\n    defer allocator.free(pair.first);\n    defer allocator.free(pair.second);\n    try std.testing.expectEqualStrings("hello", pair.first);\n    try std.testing.expectEqualStrings("zig", pair.second);\n}\n' + test('success and every allocation failure', '    try std.testing.checkAllAllocationFailures(std.testing.allocator, checkPair, .{});'),
      ['The starter leaks first if the second dupe fails.', 'Add errdefer allocator.free(first) immediately after the first successful allocation.'], 'errdefer'),
    quiz('quiz-memory', 'Checkpoint: memory', [
      q('When does defer execute?', ['Only on success', 'At the end of its scope, including error returns', 'At the start of the next function'], 1, 'defer handles cleanup on all exits from its scope. Multiple defers run in reverse registration order.'),
      q('Who frees an owned slice returned by a function?', ['The compiler always does', 'Nobody; slices are garbage collected', 'The caller, according to the ownership contract'], 2, 'A slice is a view, not an automatic owner. The API must establish who frees its backing memory.'),
      q('Why use errdefer after the first of two allocations?', ['To release the first if later work fails', 'To free the first before returning success', 'To ignore an OutOfMemory error'], 0, 'errdefer cleans up partial work on error while preserving returned ownership on success.'),
    ]),
  ]),
  chapter('compile-time', 'Think at compile time', 'Generic code, generated types, and strong tests.', '07', [
    code('comptime', 'A type from a value', 11, 'Use a compile-time parameter as an array length.',
      'A comptime parameter must be known during compilation. That makes it suitable for building a type. Array lengths are part of their type, so they must be known at compile time.\n\n```zig\nfn zeros(comptime n: usize) [n]u8 {\n    return @splat(0);\n}\n```\n@splat fills an array using its inferred type. A for loop over a pointer to an array can capture pointers to elements with |*item|.',
      'Implement `filled(comptime n: usize, value: u8) [n]u8`, returning an array of n copies of value. n can be zero; value may only be known at runtime.',
      'pub fn filled(comptime n: usize, value: u8) [n]u8 {\n    _ = value;\n    return @splat(0);\n}\n',
      'pub fn filled(comptime n: usize, value: u8) [n]u8 {\n    var result: [n]u8 = undefined;\n    for (&result) |*item| item.* = value;\n    return result;\n}\n',
      test('length-specialized arrays', '    const a = learner.filled(4, 7);\n    try std.testing.expectEqualSlices(u8, &.{ 7, 7, 7, 7 }, &a);\n    const empty = learner.filled(0, 3);\n    try std.testing.expectEqual(@as(usize, 0), empty.len);\n    var runtime: u8 = 9;\n    _ = &runtime;\n    const b = learner.filled(2, runtime);\n    try std.testing.expectEqualSlices(u8, &.{ 9, 9 }, &b);'),
      ['Create var result: [n]u8 = undefined, then initialize every element.', 'for (&result) |*item| item.* = value; handles runtime values and zero-length arrays.'], 'comptime'),
    code('generics', 'Types are values, too', 10, 'Write one function for several numeric types.',
      'In Zig, a type is a compile-time value. A comptime T: type parameter lets later parameters and the return value use that type. The compiler checks each concrete use of your generic function.\n\n```zig\nfn identity(comptime T: type, value: T) T {\n    return value;\n}\n```\nYou can call identity(u16, 42) or identity(f32, 2.5). No separate template language is needed.',
      'Implement `larger(comptime T: type, a: T, b: T) T` for comparable numeric types. Return a if a >= b, otherwise b. Tests use signed integers, unsigned integers, and floats.',
      'pub fn larger(comptime T: type, a: T, b: T) T {\n    return if (a < b) a else b;\n}\n',
      'pub fn larger(comptime T: type, a: T, b: T) T {\n    return if (a >= b) a else b;\n}\n',
      test('generic comparison', '    try std.testing.expectEqual(@as(i32, -2), learner.larger(i32, -2, -9));\n    try std.testing.expectEqual(@as(u64, 99), learner.larger(u64, 12, 99));\n    try std.testing.expectEqual(@as(f64, 3.5), learner.larger(f64, 3.5, 1.25));\n    try std.testing.expectEqual(@as(i16, 8), learner.larger(i16, 8, 8));'),
      ['The starter chooses the smaller value.', 'Use a >= b in the condition to return a for equality too.'], 'Generic-Data-Structures'),
    code('testing', 'Trust the edge cases', 13, 'Build a small algorithm with a meaningful test suite.',
      'A test block runs under zig test. std.testing.expect checks a boolean; expectEqual checks values; expectError checks an error union. Use try because assertions themselves can fail.\n\n```zig\ntest "zero is even" {\n    try std.testing.expect(isEven(0));\n}\n```\nStrong tests include small inputs, boundaries, and cases that almost meet a condition. A prime is an integer greater than one with no positive divisors except one and itself.',
      'Implement `isPrime(n: u32) bool`. Cover 0, 1, 2, even numbers, and perfect squares. Avoid d * d overflow by looping while d <= n / d. Add a test block of your own; the Check solution tests remain available in the Tests tab.',
      'const std = @import("std");\n\npub fn isPrime(n: u32) bool {\n    return n > 1;\n}\n\ntest "two is prime" {\n    try std.testing.expect(isPrime(2));\n}\n',
      'const std = @import("std");\n\npub fn isPrime(n: u32) bool {\n    if (n < 2) return false;\n    var d: u32 = 2;\n    while (d <= n / d) : (d += 1) {\n        if (n % d == 0) return false;\n    }\n    return true;\n}\n\ntest "squares are composite" {\n    try std.testing.expect(!isPrime(49));\n}\n',
      test('primes and near misses', '    try std.testing.expect(!learner.isPrime(0));\n    try std.testing.expect(!learner.isPrime(1));\n    try std.testing.expect(learner.isPrime(2));\n    try std.testing.expect(learner.isPrime(97));\n    try std.testing.expect(!learner.isPrime(49));\n    try std.testing.expect(!learner.isPrime(100));\n    try std.testing.expect(learner.isPrime(4294967291));'),
      ['Return false for n < 2. Try divisors starting at 2.', 'If n % d == 0, return false. If the loop finds no divisor, return true.'], 'Zig-Test'),
    quiz('quiz-comptime', 'Checkpoint: compile time', [
      q('Why must n be comptime in a function returning [n]u8?', ['All loop lengths must be compile-time constants', 'Array length is part of the return type', 'u8 values cannot exist at runtime'], 1, 'The compiler must know the function’s concrete return type, including the array length.'),
      q('What does comptime T: type let a function receive?', ['A type known at compile time', 'A runtime string with a type name', 'An automatically allocated object'], 0, 'Types are compile-time values in Zig and can be passed to generic functions.'),
      q('Which input is especially useful for catching an incorrect primality loop bound?', ['A random large number only', 'The number 2 only', 'A perfect square such as 49'], 2, 'A perfect square catches the mistake of stopping before testing the square-root divisor.'),
    ]),
  ]),
  chapter('ledger-project', 'Build: a tiny ledger', 'Turn text into a tested, useful program.', '08', [
    code('parse-entry', 'Project 1: read an entry', 14, 'Parse a tiny data format and reject malformed input.',
      'Our ledger stores one signed transaction per line, such as +120 or -35. std.fmt.parseInt(T, text, base) parses an integer and returns an error for invalid characters or overflow. std.mem.trim removes selected bytes from both ends.\n\n```zig\nconst cleaned = std.mem.trim(u8, line, " \\t\\r");\nconst number = try std.fmt.parseInt(i32, cleaned, 10);\n```\nAn application can map lower-level errors into a smaller public error set with catch return error.InvalidEntry.',
      'Implement `parseEntry(line) !i32`. Trim spaces, tabs, and carriage returns. Require + or - followed by at least one decimal digit. Reject underscores and all other characters. Parse into i32. Map every invalid or overflowing entry to error.InvalidEntry.',
      'const std = @import("std");\n\npub fn parseEntry(line: []const u8) !i32 {\n    return std.fmt.parseInt(i32, line, 10) catch error.InvalidEntry;\n}\n',
      'const std = @import("std");\n\npub fn parseEntry(line: []const u8) !i32 {\n    const text = std.mem.trim(u8, line, " \\t\\r");\n    if (text.len < 2) return error.InvalidEntry;\n    if (text[0] != \'+\' and text[0] != \'-\') return error.InvalidEntry;\n    for (text[1..]) |byte| {\n        if (byte < \'0\' or byte > \'9\') return error.InvalidEntry;\n    }\n    return std.fmt.parseInt(i32, text, 10) catch error.InvalidEntry;\n}\n',
      test('signed entries and whitespace', '    try std.testing.expectEqual(@as(i32, 120), try learner.parseEntry("+120"));\n    try std.testing.expectEqual(@as(i32, -35), try learner.parseEntry("  -35\\r"));\n    try std.testing.expectEqual(@as(i32, 0), try learner.parseEntry("+0"));\n    try std.testing.expectEqual(@as(i32, -2147483648), try learner.parseEntry("-2147483648"));') + test('malformed and overflow', '    for ([_][]const u8{ "", "+", "12", "+1_0", "++2", "+cat", "+2147483648" }) |line| {\n        try std.testing.expectError(error.InvalidEntry, learner.parseEntry(line));\n    }'),
      ['Trim first; validate the sign and every remaining byte before parseInt.', 'parseInt accepts some forms the format does not allow, so explicit validation matters. Map parse errors with catch error.InvalidEntry.'], 'Errors'),
    code('ledger-total', 'Project 2: follow the balance', 15, 'Compose parsing, slices, loops, and error handling.',
      'std.mem.splitScalar(u8, text, \'\\n\') creates an iterator over lines. Calling next() returns ?[]const u8. A while loop can unwrap each optional result.\n\n```zig\nvar lines = std.mem.splitScalar(u8, text, \'\\n\');\nwhile (lines.next()) |line| {\n    // inspect each line\n}\n```\nBlank lines can be skipped after trimming. Reuse the parser supplied below, propagate its errors with try, and accumulate in i64.',
      'Implement `ledgerTotal(text) !i64`: split on newlines, skip blank/whitespace-only lines, parse each entry using the supplied parseEntry, and sum its value in i64. Propagate error.InvalidEntry. Keep the parser intact.',
      'const std = @import("std");\n\npub fn parseEntry(line: []const u8) !i32 {\n    const text = std.mem.trim(u8, line, " \\t\\r");\n    if (text.len < 2 or (text[0] != \'+\' and text[0] != \'-\')) return error.InvalidEntry;\n    for (text[1..]) |b| {\n        if (b < \'0\' or b > \'9\') return error.InvalidEntry;\n    }\n    return std.fmt.parseInt(i32, text, 10) catch error.InvalidEntry;\n}\n\npub fn ledgerTotal(text: []const u8) !i64 {\n    return text.len;\n}\n',
      'const std = @import("std");\n\npub fn parseEntry(line: []const u8) !i32 {\n    const text = std.mem.trim(u8, line, " \\t\\r");\n    if (text.len < 2 or (text[0] != \'+\' and text[0] != \'-\')) return error.InvalidEntry;\n    for (text[1..]) |b| {\n        if (b < \'0\' or b > \'9\') return error.InvalidEntry;\n    }\n    return std.fmt.parseInt(i32, text, 10) catch error.InvalidEntry;\n}\n\npub fn ledgerTotal(text: []const u8) !i64 {\n    var total: i64 = 0;\n    var lines = std.mem.splitScalar(u8, text, \'\\n\');\n    while (lines.next()) |line| {\n        if (std.mem.trim(u8, line, " \\t\\r").len == 0) continue;\n        total += try parseEntry(line);\n    }\n    return total;\n}\n',
      test('multi-line ledger', '    try std.testing.expectEqual(@as(i64, 85), try learner.ledgerTotal("+120\\n-35\\n"));\n    try std.testing.expectEqual(@as(i64, 0), try learner.ledgerTotal(" \\n\\t\\n"));\n    try std.testing.expectEqual(@as(i64, 4294967294), try learner.ledgerTotal("+2147483647\\n+2147483647"));\n    try std.testing.expectEqual(@as(i64, -5), try learner.ledgerTotal("-10\\r\\n+5"));\n    try std.testing.expectError(error.InvalidEntry, learner.ledgerTotal("+10\\ninvalid\\n-1"));'),
      ['Create a line iterator and a total initialized to zero.', 'Skip trimmed empty lines, then total += try parseEntry(line).'], 'while'),
    code('ledger-report', 'Project 3: tell the story', 16, 'Summarize transactions in a useful struct.',
      'A report can return several related results in one struct. Initialize it with .{} when every field has a default. A single pass can track count, balance, and the largest positive transaction.\n\n```zig\nvar report = Report{};\nfor (entries) |entry| {\n    report.count += 1;\n    report.balance += entry;\n}\n```\nOur report uses ?u32 for the largest deposit. null means there were no strictly positive entries, which is more precise than using zero as a sentinel.',
      'Implement `summarize(entries: []const i32) Report`. Count every transaction, sum the balance in i64, and set largest_deposit to the largest strictly positive entry or null. This completes the ledger’s core. You can combine it with the earlier parser in the playground.',
      'pub const Report = struct {\n    count: usize = 0,\n    balance: i64 = 0,\n    largest_deposit: ?u32 = null,\n};\n\npub fn summarize(entries: []const i32) Report {\n    return .{ .count = entries.len };\n}\n',
      'pub const Report = struct {\n    count: usize = 0,\n    balance: i64 = 0,\n    largest_deposit: ?u32 = null,\n};\n\npub fn summarize(entries: []const i32) Report {\n    var report = Report{};\n    for (entries) |entry| {\n        report.count += 1;\n        report.balance += entry;\n        if (entry > 0) {\n            const deposit: u32 = @intCast(entry);\n            report.largest_deposit = @max(report.largest_deposit orelse 0, deposit);\n        }\n    }\n    return report;\n}\n',
      test('full report', '    const report = learner.summarize(&.{ 120, -35, 200, -10, 0 });\n    try std.testing.expectEqual(@as(usize, 5), report.count);\n    try std.testing.expectEqual(@as(i64, 275), report.balance);\n    try std.testing.expectEqual(@as(?u32, 200), report.largest_deposit);') + test('absence and wide balance', '    const empty = learner.summarize(&.{});\n    try std.testing.expectEqual(@as(usize, 0), empty.count);\n    try std.testing.expectEqual(@as(i64, 0), empty.balance);\n    try std.testing.expectEqual(@as(?u32, null), empty.largest_deposit);\n    try std.testing.expectEqual(@as(?u32, null), learner.summarize(&.{ -1, 0 }).largest_deposit);\n    try std.testing.expectEqual(@as(i64, 4294967294), learner.summarize(&.{ 2147483647, 2147483647 }).balance);'),
      ['Use var report = Report{} and update it once per entry.', 'For positive entries, compare against report.largest_deposit orelse 0. Cast to u32 only after checking entry > 0.'], 'struct'),
    quiz('quiz-project', 'Final checkpoint', [
      q('Why use i64 to accumulate i32 ledger entries?', ['It removes the need to parse', 'Several valid i32 entries can sum beyond i32', 'It makes all possible ledger sizes overflow-proof'], 1, 'A wider accumulator handles larger totals, though even i64 has a finite range.'),
      q('Why does largest_deposit use ?u32?', ['null can express that no positive deposit exists', 'Optional integers allocate automatically', 'It makes negative values valid'], 0, 'An optional distinguishes the absence of a deposit from an actual numeric amount.'),
      q('What should you do next to turn the core into a complete CLI?', ['Discard tests once it works', 'Move compilation to a remote service', 'Add input/output, document ownership, and keep testing malformed data'], 2, 'The parser and report form a reusable core. A CLI adds input/output around that core, with the same explicit error and resource handling.'),
    ]),
  ]),
];

export const chapters = [...zigChapters.map(ch => ({ ...ch, trackId: 'zig' })), ...zigTigerStyleChapters, ...tigerbeetleChapters];
export const tracks = [
  { id: 'zig', title: 'Zig foundations', version: ZIG_VERSION, description: 'Learn Zig, then practice TigerStyle and the language patterns used inside TigerBeetle.', hero: 'Small steps.', heroAccent: 'Real systems skills.' },
  { id: 'tigerbeetle', title: 'TigerBeetle project', version: TB_VERSION, description: 'Use the real database, understand its Zig codebase, and practice contributing with evidence.', hero: 'From first transfer', heroAccent: 'to the source code.' },
];
export const lessons = chapters.flatMap(ch => ch.lessons.map(lesson => ({ ...lesson, chapterId: ch.id, trackId: ch.trackId })));
export const lessonById = new Map(lessons.map(lesson => [lesson.id, lesson]));
export const playgroundStarter = `const std = @import("std");\n\npub fn main() void {\n    std.debug.print("Welcome to your Zig workshop!\\n", .{});\n    const tools = [_][]const u8{ "curiosity", "a compiler", "practice" };\n    for (tools, 1..) |tool, number| {\n        std.debug.print("{d}. {s}\\n", .{ number, tool });\n    }\n}\n\ntest "a small beginning" {\n    try std.testing.expectEqual(@as(u32, 4), 2 + 2);\n}\n`;

export function publicCourse() {
  return {
    version: ZIG_VERSION, playgroundStarter, tracks,
    chapters: chapters.map(ch => ({ ...ch, lessons: ch.lessons.map(({ solution, questions, setup, checks, sourceAnswers, ...lesson }) => ({
      ...lesson,
      ...(lesson.id === 'hello-zig' ? { expectedOutput: 'Hello, Zig!\n' } : {}),
      ...(questions ? { questions: questions.map(({ answer, explanation, ...question }) => question) } : {}),
    })) })),
  };
}

export function gradeQuiz(lesson, answers) {
  if (!Array.isArray(answers) || answers.length !== lesson.questions.length || answers.some((a, i) => !Number.isInteger(a) || a < 0 || a >= lesson.questions[i].options.length)) {
    throw new Error('Answer every question before checking the quiz.');
  }
  const results = lesson.questions.map((question, index) => ({ correct: answers[index] === question.answer, answer: question.answer, explanation: question.explanation }));
  return { passed: results.every(result => result.correct), score: results.filter(result => result.correct).length, total: results.length, results };
}
